sp_header_footer.client_script:
api.controller = function ($rootScope, $scope, $injector, spUtil, $location,
                           $uibModal, cabrillo, $timeout, $window, i18n) {

  $scope.logoText = i18n.format(
    i18n.getMessage('Go to {0} Homepage'), $scope.portal.title
  );

  $scope.collapse = function() {
    $rootScope.$emit('sp-navbar-collapse');
  };

  $scope.avatarProfile = {
    userID:   $scope.user,
    name:     $scope.user.name,
    initials: $window.NOW && $window.NOW.user_initials
              ? $window.NOW.user_initials : ''
  };
  if ($window.NOW && $window.NOW.user_avatar)
    $scope.avatarProfile.userImage = $window.NOW.user_avatar;

  // Native app check
  try {
    if (cabrillo.isNative()) {
      $scope.isViewNative       = $window.innerWidth < 767;
      $scope.isViewNativeTablet = $window.innerWidth >= 767;
    }
  } catch(e) {}

  // ── Build logoutUrl ONCE on init and bind to scope ──
  (function buildLogoutUrl() {
    var url = null;
    try { url = $scope.portal && $scope.portal.logoutUrl; } catch(e) {}
    if (!url || url === '/logout.do' || url.trim() === '') {
      try {
        var s = $scope.$parent;
        while (s) {
          if (s.portal && s.portal.logoutUrl && s.portal.logoutUrl !== '/logout.do') {
            url = s.portal.logoutUrl;
            break;
          }
          s = s.$parent;
        }
      } catch(e) {}
    }
    if (!url || url === '/logout.do' || url.trim() === '') {
      url = '/applicant?id=login&sysparm_logout=true';
    }
    $scope.logoutUrl = url;
  })();

  $scope.openPopUp = function() {
    var url = "$chat_support.do?queueID=" + $scope.data.connect_support_queue_id;
    $location.url(url, "popup", "width=900, height=600");
  };

  $scope.openLogin = function() {
    $scope.modalInstance = $uibModal.open({
      templateUrl: 'modalLogin',
      scope: $scope
    });
    var pageRoot = angular.element('.sp-page-root');
    $scope.modalInstance.rendered.then(function() {
      try {
        var $uibModalStack = $injector.get('$uibModalStack');
        var modalObj       = $uibModalStack.getTop();
        var modal          = modalObj.value.modalDomEl;
        modal.attr('aria-label', modal.find('.panel-title').html());
        modal.attr('aria-modal', 'true');
        pageRoot.attr('aria-hidden', 'true');
      } catch(e) {}
    });
    $scope.modalInstance.closed.then(function() {
      pageRoot.attr('aria-hidden', 'false');
    });
  };

  // ── Responsive avatar logic ──
  var nav = document.getElementById('responsiveNav');
  function isMDScreenSize() {
    return nav ? nav.classList.contains('responsive-tablet') : false;
  }
  function updateResponsiveClasses(width) {
    if (!nav) return;
    if (width <= 992) {
      nav.classList.add('responsive-tablet');
      nav.classList.remove('responsive-desktop');
    } else {
      nav.classList.add('responsive-desktop');
      nav.classList.remove('responsive-tablet');
    }
    $scope.showSMAvatar = isMDScreenSize();
    $scope.showAvatar   = !isMDScreenSize();
  }
  $scope.showSMAvatar = isMDScreenSize();
  $scope.showAvatar   = !isMDScreenSize();

  // ── Reserve space for the fixed pill so page content never
  //    scrolls underneath it, regardless of page template ──
  function updateNavOffset() {
    if (!nav) return;
    var rect = nav.getBoundingClientRect();
    // gap above the pill (from .gn-navbar's `top`) + pill height + a little breathing room
    var topGap = parseFloat(getComputedStyle(nav).top) || 20;
    var offset = Math.ceil(rect.height + topGap + 20);
    document.documentElement.style.setProperty('--gn-navbar-offset', offset + 'px');
  }
  // Run after layout settles (fonts/images can still shift height on first paint)
  $timeout(updateNavOffset, 0);
  $timeout(updateNavOffset, 300);
  window.addEventListener('resize', updateNavOffset);
  $scope.$on('$destroy', function() {
    window.removeEventListener('resize', updateNavOffset);
  });

  try {
    $scope.isAgentChatConfigured =
      (typeof g_has_agent_chat_config !== 'undefined')
        ? g_has_agent_chat_config : false;
  } catch(e) {
    $scope.isAgentChatConfigured = false;
  }

  if (nav) {
    try {
      new ResizeObserver(function(entries) {
        if (entries && entries[0])
          updateResponsiveClasses(entries[0].contentRect.width);
        // Mobile menu opening/closing changes the pill's real height too
        updateNavOffset();
      }).observe(nav);
    } catch(e) {}
  }

  $rootScope.$on('sp.avatar_changed', function(evt, obj) {
    $scope.userID      = "";
    $scope.newAvatarId = obj.newAvatarId;
    $timeout(function() {
      $scope.userID = $scope.user;
      $("#gn-profile-dropdown .sub-avatar").css("background-image",
        'url("' + $scope.newAvatarId + '.iix?t=small")');
    });
  });

  $scope.isHomepage = function() {
    if (!$scope.page || !$scope.page.id) return true;
    return $scope.page.id === $scope.portal.homepage_dv;
  };
};

sp_header_footer.css:
/* ═══════════════════════════════════════════════════════
   GateNow Header Widget Styles — pill navbar
   ═══════════════════════════════════════════════════════ */

/* ─── Navbar shell (floating) ───────────────────────────
   position: absolute (not fixed) — it sits 5px from the top of the
   document and scrolls away with the page, instead of staying pinned
   to the viewport. That's what stops it overlapping page content on
   scroll (no fixed element means nothing to overlap). It's still
   taken out of normal flow though, so the --gn-navbar-offset /
   body padding-top trick further down is still required to reserve
   its space. */
.gn-navbar {
  position: absolute !important;
  top: 10px;
  left: 20px;
  right: 20px;
  z-index: 1050;
  background: transparent !important;
  border: none !important;
  min-height: auto !important;
  margin-bottom: 0 !important;
}

/* ─── The actual white pill ──────────────────────────── */
.gn-navbar-inner {
  max-width: 1440px;
  width: 100%;
  margin: 0 auto;
  background: #ffffff;
  border-radius: 999px;
  box-shadow: 0 12px 30px rgba(20, 30, 70, 0.10), 0 2px 8px rgba(20, 30, 70, 0.06);
  padding: 6px 8px 6px 22px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
}

/* ─── Brand / Logo ───────────────────────────────────── */
.navbar-header.gn-navbar-brand-wrap {
  float: none !important;
  height: 64px;
  display: flex;
  align-items: center;
}

.gn-brand {
  display: flex !important;
  align-items: center;
  gap: 10px;
  padding: 0 !important;
  height: 64px !important;
  text-decoration: none !important;
}

.gn-brand:hover { background: transparent !important; opacity: 0.85; }

/* Uploaded logo image — primary. object-fit:contain preserves its own
   aspect ratio so it won't stretch or crop regardless of source size. */
.gn-logo-img {
  height: 34px;
  width: auto;
  max-width: 200px;
  object-fit: contain;
  display: block;
}

/* Fallback icon+text — only shown by the <img>'s onerror handler */
.gn-brand-text-fallback {
  display: none; /* JS flips to flex on image load failure */
  align-items: center;
  gap: 10px;
}

/* Rounded-square blue mark */
.gn-logo-mark {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 10px;
  background: linear-gradient(135deg, $gn-navbar-accent 0%, $gn-navbar-accent-dark 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.gn-logo-icon { width: 18px; height: 18px; display: block; }

/* Wordmark */
.gn-brand-text {
  font-family: 'Plus Jakarta Sans', 'Inter', 'Segoe UI', sans-serif;
  font-size: 19px;
  font-weight: 700;
  color: $gn-navbar-text;
  letter-spacing: -0.3px;
  line-height: 1;
}

/* ─── Right-side collapse panel (holds center menu + actions
       in the DOM so the mobile hamburger can toggle both at
       once — desktop CSS below visually pulls the menu to the
       true center regardless of this DOM nesting) ─────────── */
.gn-navbar-right {
  display: flex !important;
  align-items: center;
  justify-content: flex-end;
  float: none !important;
  margin: 0 !important;
  height: 64px;
  gap: 8px;
  flex: 1;
}

/* ─── Center menu (About / Programs / Process / FAQ) ─────
   Absolutely centered on .gn-navbar-inner on desktop, so it
   stays dead-center no matter how wide the logo or the
   sign-in/CTA group are. Falls back to normal static flow
   inside the collapse panel on mobile (see media query). ─ */
.gn-nav-menu {
  display: flex;
  align-items: center;
  list-style: none;
  margin: 0;
  padding: 0;
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}

.gn-nav-menu a {
  display: flex !important;
  align-items: center;
  height: 64px;
  padding: 0 16px !important;
  color: $gn-navbar-text !important;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  font-size: 15px;
  font-weight: 500;
  text-decoration: none !important;
  background: transparent !important;
  white-space: nowrap;
  transition: color 0.18s ease;
}
.gn-nav-menu a:hover { color: $gn-navbar-accent !important; }

.gn-nav-actions {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}

/* ─── Sign in (text link) ─────────────────────────────── */
.gn-signin-link {
  display: flex !important;
  align-items: center;
  height: 64px;
  padding: 0 16px !important;
  color: $gn-navbar-text !important;
  text-decoration: none !important;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  font-size: 15px;
  font-weight: 500;
  background: transparent !important;
  transition: color 0.18s ease;
}
.gn-signin-link:hover { color: $gn-navbar-accent !important; background: transparent !important; }

/* ─── Apply for funding (CTA pill) ────────────────────── */
.gn-cta-btn {
  display: flex !important;
  align-items: center;
  justify-content: center;
  height: 48px;
  padding: 0 24px !important;
  margin-left: 4px;
  border-radius: 999px;
  background: $gn-navbar-accent !important;
  color: #ffffff !important;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  font-size: 15px;
  font-weight: 700;
  text-decoration: none !important;
  white-space: nowrap;
  box-shadow: 0 0 0 4px $gn-navbar-accent-ring;
  transition: background 0.18s ease, transform 0.12s ease;
}
.gn-cta-btn:hover { background: $gn-navbar-accent-dark !important; transform: translateY(-1px); color: #fff !important; }

/* Browser default focus/active outline is rectangular and ignores
   border-radius — without this override, clicking or tabbing to the
   button makes it visually flash square. Swap the native outline for
   a rounded box-shadow ring instead, so keyboard focus is still
   visible but stays pill-shaped. */
.gn-cta-btn:focus,
.gn-cta-btn:active {
  outline: none !important;
  box-shadow: 0 0 0 4px $gn-navbar-accent-ring, 0 0 0 2px $gn-navbar-accent !important;
}

/* ─── Generic nav link (Live Chat, mobile logout) ─────── */
.gn-nav-link {
  display: flex !important;
  align-items: center;
  height: 56px;
  padding: 0 16px !important;
  color: $gn-navbar-text !important;
  font-size: 15px;
  text-decoration: none !important;
  transition: color 0.18s ease;
}
.gn-nav-link:hover { color: $gn-navbar-accent !important; }

/* ─── Avatar dropdown button ──────────────────────────── */
.gn-avatar-dropdown { position: relative; }

.gn-avatar-btn {
  display: flex !important;
  align-items: center;
  gap: 8px;
  height: 64px;
  padding: 0 10px !important;
  color: $gn-navbar-text !important;
  text-decoration: none !important;
  font-size: 15px;
  font-weight: 500;
  background: transparent !important;
  transition: opacity 0.18s ease;
  cursor: pointer;
}
.gn-avatar-btn:hover { opacity: 0.75; background: transparent !important; }

.gn-user-name { color: $gn-navbar-text; font-size: 15px; font-family: 'Inter', sans-serif; }

.gn-chevron { width: 12px; height: 12px; flex-shrink: 0; margin-left: 2px; transition: transform 0.2s ease; }
.gn-avatar-dropdown.open .gn-chevron { transform: rotate(180deg); }

/* ─── Dropdown menu ────────────────────────────────────── */
.gn-dropdown-menu {
  border: none !important;
  border-radius: 12px !important;
  box-shadow: 0 8px 32px rgba(0,0,0,0.14), 0 2px 8px rgba(0,0,0,0.08) !important;
  padding: 6px !important;
  min-width: 170px !important;
  background: #ffffff !important;
  top: calc(100% + 10px) !important;
  right: 0 !important;
  left: auto !important;
}

.gn-dropdown-header { padding: 8px 14px 4px; display: flex; flex-direction: column; }
.gn-dropdown-name { font-family: 'Inter', sans-serif; font-size: 13.5px; font-weight: 600; color: $gn-navbar-text; }
.gn-dropdown-role { font-family: 'Inter', sans-serif; font-size: 11.5px; color: $gn-navbar-sub-text; }
.gn-dropdown-divider { height: 1px; background: $brand-primary-lightest; margin: 6px 4px; }

.gn-dropdown-item {
  display: flex !important;
  align-items: center;
  gap: 8px;
  padding: 9px 14px !important;
  border-radius: 8px !important;
  color: #1D1D2E !important;
  font-size: 13.5px !important;
  font-family: 'Inter', sans-serif;
  transition: background 0.15s ease !important;
  text-decoration: none !important;
}
.gn-dropdown-item:hover { background: rgba($gn-navbar-accent, 0.08) !important; color: $gn-navbar-accent !important; }
.gn-dropdown-item:hover svg path,
.gn-dropdown-item:hover svg circle { stroke: $gn-navbar-accent !important; }

.gn-dropdown-logout:hover { background: $state-danger-bg !important; color: $brand-danger !important; }
.gn-dropdown-logout:hover svg path { stroke: $brand-danger !important; }

/* ─── Mobile hamburger ─────────────────────────────────── */
.gn-hamburger {
  border: 1.5px solid #E3E7F0 !important;
  border-radius: 8px !important;
  margin: 0 4px 0 0 !important;
  background: transparent !important;
  padding: 8px 10px !important;
  transition: background 0.18s ease;
}
.gn-hamburger:hover { background: $body-bg !important; }
.gn-hamburger .icon-bar { background: $gn-navbar-text !important; }

/* ─── Responsive ────────────────────────────────────────── */

/* Hamburger + collapse panel only exist for < 768px — hide/show
   explicitly instead of relying on the theme's default Bootstrap
   breakpoints, since we've overridden almost everything else. */
.gn-hamburger { display: none; }

@media (max-width: 992px) {
  .gn-navbar { left: 12px; right: 12px; top: 5px; }
  .gn-navbar-inner { padding: 6px 6px 6px 16px; }
}

@media (max-width: 768px) {
  .gn-hamburger { display: inline-flex; }

  .gn-navbar-right {
    height: auto !important;
    flex-direction: column;
    align-items: stretch;
    background: #ffffff;
    border-radius: 20px;
    box-shadow: 0 12px 30px rgba(20,30,70,0.12);
    margin-top: 10px;
    padding: 10px;
    gap: 2px;
    max-height: calc(100vh - 100px);
    overflow-y: auto;
  }
  /* Drop out of absolute centering — flow normally, stacked, inside
     the collapsed panel alongside Sign in / Apply for funding */
  .gn-nav-menu {
    position: static;
    left: auto; top: auto; transform: none;
    display: flex;
    flex-direction: column;
    align-items: stretch;
  }
  .gn-nav-menu a { height: 44px; padding: 0 14px !important; }
  .gn-signin-link, .gn-nav-link, .gn-avatar-btn { height: 44px; padding: 0 14px !important; }
  .gn-cta-btn { margin: 6px 4px 0; height: 44px; }
}

/* Small phones — logo + hamburger need to squeeze into much less
   width. Shrink the logo, tighten the pill's own padding, and drop
   the wordmark's letter-spacing so it doesn't wrap or force a
   horizontal scrollbar. */
@media (max-width: 420px) {
  .gn-navbar { left: 8px; right: 8px; }
  .gn-navbar-inner { padding: 6px 4px 6px 12px; height: 56px; }
  .navbar-header.gn-navbar-brand-wrap { height: 56px; }
  .gn-brand, .gn-brand-text-fallback { height: 56px !important; gap: 8px; }
  .gn-logo-img { height: 26px; max-width: 120px; }
  .gn-logo-mark { width: 28px; height: 28px; }
  .gn-brand-text { font-size: 16px; }
  .gn-hamburger { padding: 6px 8px !important; }
}

/* ─── Page body offset (header floats above the page) ───
   Absolute positioning takes the pill out of normal flow, so nothing
   pushes page content down automatically — and different page
   templates (homepage hero, register/form pages, etc.) don't all
   share the same wrapper class. Instead of hardcoding one selector,
   the controller below measures the real pill height on load/resize
   and writes it to --gn-navbar-offset on <html>. This rule applies
   it to <body>, which every page template inherits from. The 96px
   is only a fallback for the instant before JS runs. */
html { --gn-navbar-offset: 96px; }
body { padding-top: var(--gn-navbar-offset) !important; }

sp_header_footer.script:
(function() {

  data.connect_support_queue_id = $sp.getValue('sp_chat_queue');
  data.login_page   = $sp.getValue('login_page');
  data.profileBtnMsg = gs.getMessage("User options");
  data.toggleMsg     = gs.getMessage("Toggle navigation");

  // Apply-for-funding destination — falls back to '#' so the button never breaks
  try {
    var applyPage = $sp.getValue('apply_page'); // e.g. sys_id or page id of the application form
    data.applyUrl = applyPage ? ('?id=' + applyPage) : '#';
  } catch (e) {
    data.applyUrl = '#';
  }

  // Safe menu loading
  try {
    var menu = $sp.getValue("sp_rectangle_menu");
    data.menu = $sp.getWidgetFromInstance(menu);
  } catch(e) {
    data.menu = null;
    jslog('GateNow Header - menu load error: ' + e.message, 'gatenow-header');
  }

  // Safe language selector loading
  try {
    var i18nActive = gs.isPluginActivated('com.glide.i18n');
    data.langSelector = i18nActive ? $sp.getWidget('sp-lang-selector') : "";
  } catch(e) {
    data.langSelector = "";
  }

  // Parse menu items
  if (data.menu && data.menu.data) {
    data.menu.data.replace = true;
    data.hasLogin = false;
    data.hasMenuItems = false;
    try {
      if (data.menu.data.menu && data.menu.data.menu.items) {
        data.hasMenuItems = data.menu.data.menu.items.length > 0;
        for (var i in data.menu.data.menu.items) {
          var item = data.menu.data.menu.items[i];
          if (item.type == 'page' && item.sp_page == data.login_page) {
            data.hasLogin = true;
          }
        }
      }
    } catch(e) {
      jslog('GateNow Header - menu parse error: ' + e.message, 'gatenow-header');
    }
  }

  // Safe login widget
  try {
    data.loginWidget = $sp.getWidgetFromInstance('login-modal');
  } catch(e) {
    data.loginWidget = null;
  }

})();
